from decimal import Decimal, InvalidOperation


def _field(record: dict | None, name: str) -> object:
    if not record:
        return ""
    return record.get(name, "")


def _old_field(old: dict | None, name: str, event: str) -> object:
    if event == "INSERT":
        return ""
    return _field(old, name)


def _number(value: object) -> Decimal:
    if value == "" or value is None:
        return Decimal(0)
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _lookup(
    tables: dict | None,
    table_name: str,
    key_col: str,
    key_val: object,
    out_col: str,
) -> object:
    if not tables:
        return ""

    for row in tables.get(table_name, []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_col, "") == key_val:
            return row.get(out_col, "")
    return ""


def _error(code: str, message: str) -> dict:
    return {
        "code": code,
        "message": message,
        "severity": "BLOCK",
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []

    if table == "ORD_HEADER":
        if event in ("INSERT", "UPDATE"):
            discount = _number(_field(record, "DISC_PCT"))
            if not (discount >= Decimal(0) and discount <= Decimal(100)):
                errors.append(_error("E5001", "Discount out of range"))

        if event == "UPDATE":
            discount = _number(_field(record, "DISC_PCT"))
            owner_uid = _field(record, "OWNER_UID")
            role_1 = _lookup(
                tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
            )
            role_2 = _lookup(
                tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
            )
            if discount > Decimal(20) and role_1 != "MGR" and role_2 != "ADMIN":
                errors.append(
                    _error(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

        if event == "UPDATE":
            old_status = _old_field(old, "STAT_CD", event)
            status = _field(record, "STAT_CD")
            if old_status == "I" and status != "I" and status != "X":
                errors.append(
                    _error("E5003", "Invoiced order can only be cancelled")
                )

    elif table == "ORD_LINE":
        if event in ("INSERT", "UPDATE"):
            if not (_number(_field(record, "QTY")) > Decimal(0)):
                errors.append(_error("E5004", "Quantity must be positive"))

        if event == "INSERT":
            product_id = _field(record, "PROD_ID")
            active = _lookup(
                tables, "PROD_MASTER", "PROD_ID", product_id, "ACTIVE_FLG"
            )
            if active != "Y":
                errors.append(_error("E5005", "Product not active"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
